tool_input.command:
mkdir -p /tmp/mockapi && cat > /tmp/mockapi/server.js <<'EOF'
import http from 'node:http';

const CONTRACT = {
  contractId: 'c1', contractName: 'MSA-2025-0412 — Northbridge Logistics Services Agreement',
  counterparty: 'Northbridge Logistics Inc.', status: 'Active', value: 184500,
  startDate: '2025-02-01', endDate: '2026-01-31', owner: 'Priya Anand',
  lastModified: '2026-10-02T10:00:00Z', folderTags: [],
  availableTabs: ['Details', 'Document', 'Versions', 'Activity Log'],
};

const DOCS = {
  c1: { contractId: 'c1', documentUrl: 'https://example.com/doc.pdf', fileName: 'MSA-2025-0412_v6_executed.pdf', fileType: 'PDF', fileSizeBytes: 1024, isOversized: false, isCorruptedOrMissing: false, downloadEnabled: true },
  c2: { contractId: 'c2', documentUrl: null, fileName: 'oversized.pdf', fileType: 'PDF', fileSizeBytes: 999999999, isOversized: true, isCorruptedOrMissing: false, downloadEnabled: false, unavailableComment: 'File unavailable' },
  c3: { contractId: 'c3', documentUrl: null, fileName: 'corrupted.pdf', fileType: 'PDF', fileSizeBytes: 1024, isOversized: false, isCorruptedOrMissing: true, downloadEnabled: true },
};

const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Content-Type', 'application/json');
  const url = req.url;
  const idMatch = url.match(/\/api\/v1\/contracts\/([^/]+)/);
  const id = idMatch ? idMatch[1] : 'c1';

  if (/\/document\/download$/.test(url)) {
    const doc = DOCS[id] || DOCS.c1;
    if (doc.isCorruptedOrMissing) {
      res.end(JSON.stringify({ success: false, errorMessage: 'This document could not be retrieved. Please contact your administrator.' }));
    } else {
      res.end(JSON.stringify({ success: true, fileUrl: doc.documentUrl }));
    }
    return;
  }
  if (/\/document$/.test(url)) {
    res.end(JSON.stringify(DOCS[id] || DOCS.c1));
    return;
  }
  if (/\/versions/.test(url)) { res.end(JSON.stringify({ items: [], totalCount: 0 })); return; }
  if (/\/activity-log/.test(url)) { res.end(JSON.stringify({ items: [], totalCount: 0 })); return; }
  if (idMatch) { res.end(JSON.stringify({ ...CONTRACT, contractId: id })); return; }
  res.end(JSON.stringify({}));
});
server.listen(5281, () => console.log('mock api on 5281'));
EOF
node /tmp/mockapi/server.js &
sleep 1
curl -s http://localhost:5281/api/v1/contracts/c2/document
